2	// Every file is written as { schemaVersion, generatedAt, data }, so a reader can tell which shape it
3	// is looking at without guessing from the contents. Writes are atomic: a temp file next to the target
4	// is renamed over it, so a reader never sees a half-written report and no temp file survives a run.
5	import { access, mkdir, rename, unlink, writeFile } from "node:fs/promises";
6	import { randomUUID } from "node:crypto";
7	import { dirname, join } from "node:path";
8	
9	/** Version of the `{ schemaVersion, generatedAt, data }` envelope written by exportRun. */
10	export const SCHEMA_VERSION = 1;
11	
12	/** A run as the coordinator holds it: a review, plus the plan, replays and gate decisions when there are any. */
13	export interface RunExport {
14	  review: unknown;
15	  plan?: unknown;
16	  replays?: unknown[];
17	  gate?: unknown[];
18	}
19	
20	/** The envelope every report file shares. */
21	export interface ReportFile {
22	  schemaVersion: number;
23	  generatedAt: string;
24	  data: unknown;
25	}
26	
27	/** One section of a run: the file it becomes, the RunExport key it reads, and whether it is optional. */
28	const SECTIONS = [
29	  { fileName: "review.json", key: "review", optional: false },
30	  { fileName: "plan.json", key: "plan", optional: true },
31	  { fileName: "replays.json", key: "replays", optional: true },
32	  { fileName: "gate.json", key: "gate", optional: true },
33	] as const satisfies readonly { fileName: string; key: keyof RunExport; optional: boolean }[];
34	
35	/**
36	 * Writes review.json always, and plan.json, replays.json and gate.json when the run carries them
37	 * (an optional section is absent only when it is undefined; an empty object or array still gets a
38	 * file). Each file holds `{ schemaVersion: 1, generatedAt, data }`. `outDir` is created when missing.
39	 * Returns the written paths, sorted.
40	 *
41	 * Re-export overwrites the files it writes; with identical data, generatedAt is the only field that
42	 * changes. Files the run does not ask for are left untouched, so an export never deletes unrelated
43	 * content of `outDir`.
44	 */
45	export async function exportRun(run: RunExport, outDir: string): Promise<string[]> {
46	  if (run === null || typeof run !== "object") throw new Error("exportRun: run must be an object");
47	  if (run.review === undefined) throw new Error("exportRun: run.review is required; review.json is always written");
48	
49	  // Every section is serialized before the first write, so data that cannot be encoded as JSON (a
50	  // circular reference, a BigInt, a throwing toJSON) fails the export without leaving any file behind.
51	  const generatedAt = new Date().toISOString();
52	  const files = SECTIONS.filter((s) => !s.optional || run[s.key] !== undefined).map((s) => ({
53	    fileName: s.fileName,
54	    body: JSON.stringify({ schemaVersion: SCHEMA_VERSION, generatedAt, data: run[s.key] } satisfies ReportFile, null, 2) + "\n",
55	  }));
56	
57	  await mkdir(outDir, { recursive: true });
58	
59	  const paths: string[] = [];
60	  for (const { fileName, body } of files) {
61	    const path = join(outDir, fileName);
62	    await writeAtomic(path, body);
63	    paths.push(path);
64	  }
65	  return paths.sort();
66	}
67	
68	/** Writes `body` to a unique temp file next to `path`, then renames it over `path`. */
69	async function writeAtomic(path: string, body: string): Promise<void> {
70	  const tmp = join(dirname(path), `.${randomUUID()}.tmp`);
71	  try {
72	    await writeFile(tmp, body);
73	    await rename(tmp, path);
74	  } catch (err) {
75	    // The rename either happened (and the temp file is gone) or it did not; only remove a temp file we own.
76	    if (await exists(tmp)) await unlink(tmp).catch(() => {});
77	    throw err;
78	  }
79	}
