1	import { describe, expect, test } from "bun:test";
2	import { collectCosts } from "../../scripts/costs.ts";
3	
4	type CostRow = { source: string; setup: string; costUsd: number | null };
5	
6	function replayEntry(setup: string, costUsd: number | null) {
7	  return { setup, setup_id: setup, setupId: setup, costUsd, cost_usd: costUsd };
8	}
9	
10	function forwardPair(
11	  oldSetup: string,
12	  oldCost: number | null,
13	  newSetup: string,
14	  newCost: number | null,
15	) {
16	  return {
17	    setupOld: oldSetup,
18	    setupNew: newSetup,
19	    setup_old: oldSetup,
20	    setup_new: newSetup,
21	    costOld: oldCost,
22	    costNew: newCost,
23	    cost_old: oldCost,
24	    cost_new: newCost,
25	  };
26	}
27	
28	function reviewSetup(setup: string, costUsd: number | null) {
29	  return { setup, setup_id: setup, setupId: setup, label: setup, costUsd, cost_usd: costUsd };
30	}
31	
32	function rowsMatching(rows: CostRow[], sourcePart: string): CostRow[] {
33	  return rows.filter((row) => row.source.includes(sourcePart));
34	}
35	
36	describe("collectCosts", () => {
37	  test("reads replay, forward and review costs and ignores unknown files", () => {
38	    const result = collectCosts([
39	      {
40	        path: "replays.json",
41	        json: {
42	          data: [
43	            replayEntry("setup-a", 1.5),
44	            replayEntry("setup-b", null),
45	            replayEntry("setup-c", 2.5),
46	          ],
47	        },
48	      },
49	      {
50	        path: "forward.json",
51	        json: {
52	          data: {
53	            pairs: [
54	              forwardPair("setup-old", 3.5, "setup-new", 4.5),
55	              forwardPair("setup-old2", null, "setup-new2", 6.5),
56	            ],
57	          },
58	        },
59	      },
60	      {
61	        path: "review.json",
62	        json: {
63	          data: {
64	            setups: [
65	              reviewSetup("setup-review", 7.5),
66	              reviewSetup("setup-review2", null),
67	            ],
68	          },
69	        },
70	      },
71	      {
72	        path: "unknown.json",
73	        json: { data: [{ setup: "x", costUsd: 99 }] },
74	      },
75	    ]);
76	
77	    expect(result.replayRuns).toBe(3);
78	    expect(result.forwardRuns).toBe(4);
79	    expect(result.reviewRuns).toBe(2);
80	    expect(result.rows).toHaveLength(9);
81	
82	    const replayRows = rowsMatching(result.rows, "replay");
83	    const forwardRows = rowsMatching(result.rows, "forward");
84	    const reviewRows = rowsMatching(result.rows, "review");
85	
86	    expect(replayRows).toHaveLength(3);
87	    expect(forwardRows).toHaveLength(4);
88	    expect(reviewRows).toHaveLength(2);
89	
90	    expect(replayRows.find((row) => row.setup === "setup-a")?.costUsd).toBe(1.5);
91	    expect(replayRows.find((row) => row.setup === "setup-b")?.costUsd).toBeNull();
92	    expect(replayRows.find((row) => row.setup === "setup-c")?.costUsd).toBe(2.5);
93	
94	    expect(forwardRows.find((row) => row.setup === "setup-old")?.costUsd).toBe(3.5);
95	    expect(forwardRows.find((row) => row.setup === "setup-new")?.costUsd).toBe(4.5);
96	    expect(forwardRows.find((row) => row.setup === "setup-old2")?.costUsd).toBeNull();
97	    expect(forwardRows.find((row) => row.setup === "setup-new2")?.costUsd).toBe(6.5);
98	
99	    expect(reviewRows.find((row) => row.setup === "setup-review")?.costUsd).toBe(7.5);
100	    expect(reviewRows.find((row) => row.setup === "setup-review2")?.costUsd).toBeNull();
101	  });
102	
103	  test("skips malformed entries and does not count them", () => {
104	    const result = collectCosts([
105	      {
106	        path: "replays.json",
107	        json: {
108	          data: [
109	            replayEntry("valid-replay", 1),
110	            { setup: "missing-cost", setup_id: "missing-cost", setupId: "missing-cost" },
111	            { costUsd: 2, cost_usd: 2 },
112	            { setup: "bad-cost", setup_id: "bad-cost", setupId: "bad-cost", costUsd: "bad", cost_usd: "bad" },
113	          ],
114	        },
115	      },
116	      {
117	        path: "forward.json",
118	        json: {
119	          data: {
120	            pairs: [
121	              forwardPair("valid-old", 10, "valid-new", 20),
122	              {
123	                setupOld: "missing-costs-old",
124	                setupNew: "missing-costs-new",
125	                setup_old: "missing-costs-old",
126	                setup_new: "missing-costs-new",
127	              },
128	              {
129	                setupOld: "bad-costs-old",
130	                setupNew: "bad-costs-new",
131	                setup_old: "bad-costs-old",
132	                setup_new: "bad-costs-new",
133	                costOld: "bad",
134	                costNew: "bad",
135	                cost_old: "bad",
136	                cost_new: "bad",
137	              },
138	            ],
139	          },
140	        },
141	      },
142	      {
143	        path: "review.json",
144	        json: {
145	          data: {
146	            setups: [
147	              reviewSetup("valid-review", 30),
148	              { setup: "missing-cost-review", setup_id: "missing-cost-review", setupId: "missing-cost-review", label: "missing-cost-review" },
149	              { costUsd: 40, cost_usd: 40 },
150	              { setup: "bad-cost-review", setup_id: "bad-cost-review", setupId: "bad-cost-review", label: "bad-cost-review", costUsd: "bad", cost_usd: "bad" },
151	            ],
152	          },
153	        },
154	      },
155	    ]);
156	
157	    expect(result.replayRuns).toBe(1);
158	    expect(result.forwardRuns).toBe(2);
159	    expect(result.reviewRuns).toBe(1);
160	    expect(result.rows).toHaveLength(4);
