  ["replays.json", "replay"],
  ["forward.json", "forward"],
]);

/** Candidate keys, in priority order, for the setup a run belongs to. Real exports use snake_case; replays API rows use camelCase. */
const SETUP_KEYS = ["setup", "setup_id", "setupId", "label"] as const;
/** Candidate keys for a run's cost. review.jsons written by src/review/export.ts carry spend_usd. */
const COST_KEYS = ["costUsd", "cost_usd", "spend_usd"] as const;

const isRecord = (v: unknown): v is Record<string, unknown> => typeof v === "object" && v !== null && !Array.isArray(v);

/** The first candidate key holding a string, or null. */
function firstString(obj: Record<string, unknown>, keys: readonly string[]): string | null {
  for (const key of keys) {
    const v = obj[key];
    if (typeof v === "string" && v.length > 0) return v;
  }
  return null;
}

/** A cost is a finite number or null when its first present key holds that; absent or anything else is malformed. */
function readCost(obj: Record<string, unknown>, keys: readonly string[]): { ok: true; costUsd: number | null } | { ok: false } {
  for (const key of keys) {
    const v = obj[key];
    if (v === undefined) continue;
    if (v === null) return { ok: true, costUsd: null };
    if (typeof v === "number" && Number.isFinite(v)) return { ok: true, costUsd: v };
    return { ok: false };
  }
  return { ok: false };
}

/** Zero counts and no rows, the base an unknown file contributes. */
const empty = (): CostCollection => ({ reviewRuns: 0, replayRuns: 0, forwardRuns: 0, rows: [] });

/** Collects one file's costs into `out`; a path whose basename is not a known report contributes nothing. */
function collectInto(out: CostCollection, path: string, json: unknown): void {
  const kind = KINDS.get(path.slice(path.lastIndexOf("/") + 1));
  if (kind === undefined) return;
  const data = isRecord(json) ? json.data : undefined;

  if (kind === "replay") {
    if (!Array.isArray(data)) return;
    for (const raw of data) {
      if (!isRecord(raw)) continue;
      const setup = firstString(raw, SETUP_KEYS);
      const cost = readCost(raw, COST_KEYS);
      if (setup === null || !cost.ok) continue;
      out.rows.push({ source: path, setup, costUsd: cost.costUsd });
      out.replayRuns++;
    }
    return;
  }

  if (kind === "review") {
    const setups = isRecord(data) && Array.isArray(data.setups) ? data.setups : undefined;
    if (setups === undefined) return;
    for (const raw of setups) {
      if (!isRecord(raw)) continue;
      const setup = firstString(raw, SETUP_KEYS);
      const cost = readCost(raw, COST_KEYS);
      if (setup === null || !cost.ok) continue;
      out.rows.push({ source: path, setup, costUsd: cost.costUsd });
      out.reviewRuns++;
    }
    return;
  }

  const pairs = isRecord(data) && Array.isArray(data.pairs) ? data.pairs : undefined;
  if (pairs === undefined) return;
  for (const raw of pairs) {
    if (!isRecord(raw)) continue;
    const oldSetup = firstString(raw, ["setupOld", "setup_old"]);
    const newSetup = firstString(raw, ["setupNew", "setup_new"]);
    const oldCost = readCost(raw, ["costOld", "cost_old"]);
    const newCost = readCost(raw, ["costNew", "cost_new"]);
    // A pair is one entry: a malformed side skips the pair whole, so a run is never counted half-dressed.
    if (oldSetup === null || newSetup === null || !oldCost.ok || !newCost.ok) continue;
    out.rows.push({ source: path, setup: oldSetup, costUsd: oldCost.costUsd });
    out.rows.push({ source: path, setup: newSetup, costUsd: newCost.costUsd });
    out.forwardRuns += 2;
  }
}

/** Collects the costs of the given report files. Paths are used verbatim as each row's `source`. */
export function collectCosts(files: { path: string; json: unknown }[]): CostCollection {
  const out = empty();
  for (const file of files) collectInto(out, file.path, file.json);
  return out;
}

/** Every report file under `dir` whose basename collectCosts knows, sorted by path. */
export function reportFiles(dir: string): string[] {
  const found: string[] = [];
  const walk = (at: string): void => {
    let entries;
    try {
      entries = readdirSync(at, { withFileTypes: true });
    } catch {
      return; // an unreadable directory contributes no reports
    }
    for (const e of entries) {
      const path = join(at, e.name);
      if (e.isDirectory()) walk(path);
      else if (e.isFile() && KINDS.has(e.name)) found.push(path);
    }
  };
  walk(dir);
  return found.sort();
}

/** Reads every report under `reportsDir` and collects its costs. A file that is unreadable or not JSON is ignored. */
export function collectCostsFromDir(reportsDir: string): CostCollection {
  const files = reportFiles(reportsDir).map((path) => {
    let json: unknown;
    try {
      json = JSON.parse(readFileSync(path, "utf8"));
    } catch {
      json = undefined;
    }
    return { path, json };
  });
  return collectCosts(files);
}

/** Writes reports/costs.json under `reportsDir`. Returns the path written. */
export function writeCosts(reportsDir: string, generatedAt: string = new Date().toISOString()): string {
  const report: CostsReport = { schemaVersion: 1, generatedAt, data: collectCostsFromDir(reportsDir) };
  const out = join(reportsDir, "costs.json");
  mkdirSync(reportsDir, { recursive: true });
  writeFileSync(out, JSON.stringify(report, null, 2) + "\n");
  return out;
}

if (import.meta.main) {
  const dir = process.argv[2] ?? "reports";
  const out = writeCosts(dir);
  const { reviewRuns, replayRuns, forwardRuns, rows } = JSON.parse(readFileSync(out, "utf8")).data as CostCollection;
  console.log(`wrote ${out}: ${reviewRuns} review runs, ${replayRuns} replay runs, ${forwardRuns} forward runs (${rows.length} rows)`);
}

