// The replay, forward and review entries below use the shapes the published reports carry: replays.json is the
// `{ schemaVersion, generatedAt, data }` envelope from src/report/export.ts holding Replay rows (setup_id,
// cost_usd), forward.json the same envelope holding ForwardPair rows (setup_old/setup_new, cost_old/cost_new),
// and review.json is written top-level by src/review/export.ts with SetupRow (setup_id, spend_usd). The real
// files under reports/ are the samples the disk tests read, so no number or shape here is invented.
import { describe, expect, test } from "bun:test";
import { mkdirSync, mkdtempSync, readFileSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join, resolve } from "node:path";
import { collectCosts, collectCostsFromDir, reportFiles, writeCosts } from "../scripts/costs.ts";

const REPORTS = resolve(import.meta.dir, "..", "reports");

/** An entry is valid only with both a setup and a cost field; a missing cost or a non-numeric cost is malformed. */
describe("collectCosts", () => {
  test("reads replays, forward and review rows and ignores an unknown file", () => {
    const result = collectCosts([
      {
        path: "replays.json",
        json: {
          schemaVersion: 1,
          generatedAt: "2026-10-12T00:00:00.000Z",
          data: [
            { setup_id: "setup-a", cost_usd: 1.5 },
            { setup_id: "setup-b", cost_usd: null },
            { setup_id: "setup-c", cost_usd: 2.5 },
          ],
        },
      },
      {
        path: "forward.json",
        json: {
          data: {
            pairs: [
              { setup_old: "setup-old", setup_new: "setup-new", cost_old: 3.5, cost_new: 4.5 },
              { setup_old: "setup-old2", setup_new: "setup-new2", cost_old: null, cost_new: 6.5 },
            ],
          },
        },
      },
      {
        path: "review.json",
        json: {
          setups: [
            { setup_id: "setup-review", spend_usd: 7.5 },
            { setup_id: "setup-review2", spend_usd: 0 },
          ],
        },
      },
      { path: "plan.json", json: { data: { budget_usd: 999 } } },
      { path: "unknown.json", json: { data: [{ setup: "x", costUsd: 99 }] } },
    ]);

    expect(result.replayRuns).toBe(3);
    expect(result.forwardRuns).toBe(4);
    expect(result.reviewRuns).toBe(2);
    expect(result.rows).toHaveLength(9);

    const replay = result.rows.filter((r) => r.source.includes("replay"));
    expect(replay.find((r) => r.setup === "setup-a")?.costUsd).toBe(1.5);
    expect(replay.find((r) => r.setup === "setup-b")?.costUsd).toBeNull(); // unpriced is still a run
    expect(replay.find((r) => r.setup === "setup-c")?.costUsd).toBe(2.5);

    const forward = result.rows.filter((r) => r.source.includes("forward"));
    expect(forward.find((r) => r.setup === "setup-old")?.costUsd).toBe(3.5);
    expect(forward.find((r) => r.setup === "setup-new")?.costUsd).toBe(4.5);
    expect(forward.find((r) => r.setup === "setup-old2")?.costUsd).toBeNull();
    expect(forward.find((r) => r.setup === "setup-new2")?.costUsd).toBe(6.5);

    const review = result.rows.filter((r) => r.source.includes("review"));
    expect(review.find((r) => r.setup === "setup-review")?.costUsd).toBe(7.5);
    expect(review.find((r) => r.setup === "setup-review2")?.costUsd).toBe(0);
  });

  test("skips a malformed entry and does not count it", () => {
    const result = collectCosts([
      {
        path: "replays.json",
        json: {
          data: [
            { setup_id: "valid", cost_usd: 1 },
            { setup_id: "no-cost" }, // cost field absent
            { cost_usd: 2 }, // setup absent
            { setup_id: "bad-cost", cost_usd: "bad" }, // cost is not a number
            null, // not an object
          ],
        },
      },
      {
        path: "forward.json",
        json: {
          data: {
            pairs: [
              { setup_old: "old", setup_new: "new", cost_old: 10, cost_new: 20 },
              { setup_old: "old2", setup_new: "new2" }, // both costs absent
              { setup_old: "old3", setup_new: "new3", cost_old: "bad", cost_new: 1 }, // one cost malformed skips the pair
            ],
          },
        },
      },
      {
        path: "review.json",
        json: {
          setups: [
            { setup_id: "valid-review", spend_usd: 30 },
            { setup_id: "no-cost-review" },
            { spend_usd: 40 },
            { setup_id: "bad-cost-review", spend_usd: "bad" },
          ],
        },
      },
    ]);

    expect(result.replayRuns).toBe(1);
    expect(result.forwardRuns).toBe(2);
    expect(result.reviewRuns).toBe(1);
    expect(result.rows).toHaveLength(4);
    expect(result.rows.map((r) => r.setup).sort()).toEqual(["new", "old", "valid", "valid-review"]);
    expect(result.rows.find((r) => r.setup === "valid")!.costUsd).toBe(1);
    expect(result.rows.find((r) => r.setup === "old")!.costUsd).toBe(10);
    expect(result.rows.find((r) => r.setup === "new")!.costUsd).toBe(20);
    expect(result.rows.find((r) => r.setup === "valid-review")!.costUsd).toBe(30);
  });

  test("a file with no usable section contributes nothing", () => {
    const result = collectCosts([
      { path: "replays.json", json: null },
      { path: "replays.json", json: { data: { not: "an array" } } },
      { path: "forward.json", json: {} },
      { path: "review.json", json: { setups: "nope" } },
    ]);
    expect(result).toEqual({ reviewRuns: 0, replayRuns: 0, forwardRuns: 0, rows: [] });
  });
});

describe("reports on disk", () => {
  test("the directory walk finds every cost-bearing report and no other", () => {
    const files = reportFiles(REPORTS);
    expect(files.length).toBeGreaterThan(0);
    expect(files.every((f) => /(replays|forward|review)\.json$/.test(f))).toBe(true);
    expect(files.some((f) => f.endsWith("review.json"))).toBe(true);
  });

  test("every setup's measured cost in the real reviews is collected", () => {
    const result = collectCostsFromDir(REPORTS);
    // Independent expectation: the real reviews carry their setup rows at the top level with spend_usd.
    const expected: { source: string; setup: string; costUsd: number | null }[] = [];
    for (const path of reportFiles(REPORTS).filter((f) => f.endsWith("review.json"))) {
      const json = JSON.parse(readFileSync(path, "utf8")) as { setups?: { setup_id?: string; spend_usd?: number | null }[] };
      for (const s of json.setups ?? []) {
        if (typeof s.setup_id === "string" && (s.spend_usd === null || typeof s.spend_usd === "number")) {
          expected.push({ source: path, setup: s.setup_id, costUsd: s.spend_usd ?? null });
        }
      }
    }
    expect(result.reviewRuns).toBe(expected.length);
    expect(result.rows).toEqual(expected);
  });

  test("writeCosts writes a costs.json envelope that reads back", () => {
    const dir = mkdtempSync(join(tmpdir(), "costs-script-"));
    mkdirSync(join(dir, "some-repo"));
    writeFileSync(join(dir, "some-repo", "review.json"), readFileSync(join(REPORTS, "rajkaria__roster", "review.json")));
    const at = "2026-10-12T00:00:00.000Z";

    const out = writeCosts(dir, at);
    expect(out).toBe(join(dir, "costs.json"));

    const report = JSON.parse(readFileSync(out, "utf8")) as {
      schemaVersion: number;
      generatedAt: string;
      data: { reviewRuns: number; replayRuns: number; forwardRuns: number; rows: unknown[] };
    };
    expect(report.schemaVersion).toBe(1);
    expect(report.generatedAt).toBe(at);
    expect(report.data.replayRuns).toBe(0);
    expect(report.data.forwardRuns).toBe(0);
    expect(report.data.reviewRuns).toBeGreaterThan(0);
    expect(report.data.rows).toHaveLength(report.data.reviewRuns);
    expect(report.data).toEqual(collectCostsFromDir(dir));
  });
});

